    private Location getLocation() {
        if (this.locationManager != null) {
            if (this.isAccessFineLocation == 0) {
                boolean isGpsEnabled = this.locationManager.isProviderEnabled("gps");
                if (isGpsEnabled) {
                    return this.locationManager.getLastKnownLocation("gps");
                }
            }
            if (this.isAccessCoarseLocation == 0) {
                boolean isNetworkEnabled = this.locationManager.isProviderEnabled("network");
                if (isNetworkEnabled) {
                    return this.locationManager.getLastKnownLocation("network");
                }
            }
        }
        return null;
    }

