    public static String readInputStream(BufferedInputStream in) throws IOException {
        StringBuffer out = new StringBuffer();
        byte[] buffer = new byte[8192];
        while (true) {
            int n = in.read(buffer);
            if (n != -1) {
                out.append(new String(buffer, 0, n));
            } else {
                return out.toString();
            }
        }
    }

